local config = {
  ui_story_5052_50520101_1_dialog_content = "\"...\"",
  ui_story_5052_50520101_2_dialog_content = "Halo, PlayerName.",
  ui_story_5052_50520101_3_dialog_content = "Selamat datang...",
  ui_story_5052_50520101_4_dialog_content = "... ke Aula Kebenaran.",
  ui_story_5052_50520101_5_option_content = "Siapa di sana?",
  ui_story_5052_50520101_6_dialog_content = "Halo? Apakah seseorang di sana?",
  ui_story_5052_50520101_7_dialog_content = "Aneh. Aku bersumpah aku mendengar seseorang berbicara barusan...",
  ui_story_5052_50520101_8_dialog_content = "Bagaimana saya bisa berakhir di sini? Terakhir yang saya ingat, saya sedang berjalan di jalanan Umbraton.",
  ui_story_5052_50520101_9_option_content = "Di mana aku?",
  ui_story_5052_50520101_10_dialog_content = "Tempat ini terasa agak familiar, seperti salah satunya <color=#FFB400>Pesanan Sejati</color> tempat berkumpul.",
  ui_story_5052_50520101_11_dialog_content = "Bagaimana aku bisa berakhir di sini? Terakhir yang saya ingat, saya sedang berjalan di jalanan Umbraton.",
  ui_story_5052_50520101_12_dialog_content = "<color=#e8d9bb>Sepuluh menit yang lalu</color>",
  ui_story_5052_50520101_13_dialog_content = "Halo, PlayerName.",
  ui_story_5052_50520101_14_dialog_content = "hai, Eicy! Berbelanja juga? Toko mana yang akan Anda bersihkan hari ini?",
  ui_story_5052_50520101_15_dialog_content = "Sebenarnya, ada tempat terdekat yang ingin kutunjukkan padamu.",
  ui_story_5052_50520101_16_dialog_content = "Apakah Anda punya waktu untuk memeriksanya?",
  ui_story_5052_50520101_17_dialog_content = "Tentu, saya tidak punya hal lain yang terjadi sekarang.",
  ui_story_5052_50520101_18_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5052_50520101_19_dialog_content = "Dan kemudian, dia menunjukkan mata kanannya, Hollow Gaze.",
  ui_story_5052_50520101_20_dialog_content = "Oh, aku mengerti sekarang.",
  ui_story_5052_50520101_21_dialog_content = "Jadi itu hanya pengendalian pikiran sederhana, dan saya pikir saya berjalan dalam tidur!",
  ui_story_5052_50520101_22_dialog_content = "Tapi kenapa dia membawaku ke sini?",
  ui_story_5052_50520101_23_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5052_50520101_24_dialog_content = "Hmm? Apa itu tadi?",
  ui_story_5052_50520101_25_dialog_content = "Ini <color=#FFB400>buku</color> terlihat familier juga... Apa aku pernah melihatnya di suatu tempat sebelumnya?",
  ui_story_5052_50520101_26_dialog_content = "Oh, benar! Ini adalah buku itu <color=#FFB400>Victoria</color> selalu dibawa-bawa!",
  ui_story_5052_50520101_27_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5052_50520101_28_dialog_content = "Halaman-halamannya membalik dengan sendirinya. Biarkan saya melihat apa yang ada di halaman.",
  ui_story_5052_50520101_29_dialog_content = "Hmmm, beberapa catatan ditulis untukku.",
  ui_story_5052_50520101_30_dialog_content = "\"Navigator, sekarang Anda seharusnya sudah menemukan pesan ini.\"",
  ui_story_5052_50520101_31_dialog_content = "\"Kamu akan menghadapi yang sangat unik <color=#FFB400>uji coba</color>, yang belum pernah Anda alami sebelumnya.\"",
  ui_story_5052_50520101_32_dialog_content = "\"Tapi yakinlah, itu <color=#FFB400>Buku Hitam</color> menunjukkan kebaikan kepada semua pembacanya...\"",
  ui_story_5052_50520101_33_dialog_content = "\"Anda harus merangkul perubahan jika ingin sukses, Navigator.\"",
  ui_story_5052_50520101_34_dialog_content = "\"Uji coba baru ini menantang namun cukup menyenangkan. Bahkan saya tidak dapat mencapai kesimpulannya yang gemilang.\"",
  ui_story_5052_50520101_35_dialog_content = "\"Kita harus menghadapi setiap ujiannya dengan penuh pengabdian dan ketundukan...\"",
  ui_story_5052_50520101_36_dialog_content = "\"Jangan biarkan orang-orang ini membingungkanmu, PlayerName. Sidang ini tidak serumit kelihatannya.\"",
  ui_story_5052_50520101_37_dialog_content = "\"Ini tidak lebih dari takdir yang berlalu, yang telah lama ditentukan.\"",
  ui_story_5052_50520101_38_dialog_content = "\"Ingatlah...\"",
  ui_story_5052_50520101_39_dialog_content = "\"Bakar setelah membaca.\"",
  ui_story_5052_50520101_40_dialog_content = "\"Hah? Kenapa aku harus meninggalkan pesan untuknya juga?",
  ui_story_5052_50520101_41_dialog_content = "\"Tulis saja sesuatu untukku, maukah? Ini tidak seperti PlayerName benar-benar akan membacanya atau apa pun.\"",
  ui_story_5052_50520101_42_dialog_content = "\"Kalian hebat dalam mengarang hal-hal samar yang tak seorang pun mengerti. Lakukan saja sesuatu seperti itu!\"",
  ui_story_5052_50520101_43_dialog_content = "\"Selain itu, waktunya minum teh soreku. Buh-bye!\"",
  ui_story_5052_50520101_44_dialog_content = "...",
  ui_story_5052_50520101_45_option_content = "Saya benar-benar mengerti segalanya.",
  ui_story_5052_50520101_46_dialog_content = "Kata-kata mereka tidak jelas dan membingungkan seperti biasanya, tapi kurasa aku mengerti intinya.",
  ui_story_5052_50520101_47_dialog_content = "Aku di sini untuk pergi melalui semacam <color=#FFB400>uji coba</color>, Kanan?",
  ui_story_5052_50520101_48_dialog_content = "<color=#e8d9bb>Halaman buku mulai membalik sekali lagi. Tiba-tiba, kata-kata mulai muncul di halaman kosong...</color>",
  ui_story_5052_50520101_49_dialog_content = "\"Benar.\"",
  ui_story_5052_50520101_50_option_content = "Itu pasti omong kosong.",
  ui_story_5052_50520101_51_dialog_content = "Untuk semua kata-kata sia-sia mereka, mereka mungkin juga tidak mengatakan apa-apa.",
  ui_story_5052_50520101_52_dialog_content = "Pokoknya, seperti apa <color=#FFB400>uji coba</color> yang mereka bicarakan? Apa yang mereka maksud dengan \"hal-hal yang belum pernah saya alami sebelumnya\"?",
  ui_story_5052_50520101_53_dialog_content = "<color=#e8d9bb>Halaman buku mulai membalik sekali lagi. Tiba-tiba, kata-kata mulai muncul di halaman kosong...</color>",
  ui_story_5052_50520101_54_dialog_content = "\"Artinya sangat berbeda.\"",
  ui_story_5052_50520101_55_dialog_content = "?!",
  ui_story_5052_50520101_56_dialog_content = "A-Apa benda ini menulis untukku?!",
  ui_story_5052_50520101_57_dialog_content = "\"Halo, PlayerName.\"",
  ui_story_5052_50520101_58_dialog_content = "Halo?",
  ui_story_5052_50520101_59_dialog_content = "Tunggu, bisakah buku ini benar-benar mendengar saya, atau apakah saya harus menulis tanggapan saya di dalamnya?",
  ui_story_5052_50520101_60_dialog_content = "\"Saya dapat mendengar Anda.\"",
  ui_story_5052_50520101_61_dialog_content = "Ini sangat aneh...",
  ui_story_5052_50520101_62_option_content = "Apa yang terjadi di sini?",
  ui_story_5052_50520101_63_dialog_content = "\"Aku sudah lama menunggumu.\"",
  ui_story_5052_50520101_64_dialog_content = "\"Para murid Kebenaran telah menyiapkan sejumlah <color=#FFB400>percobaan</color> untuk Anda atasi. Saya yakin Anda siap?\"",
  ui_story_5052_50520101_65_option_content = "Siapa namamu?",
  ui_story_5052_50520101_66_dialog_content = "\"Aku tidak punya nama, namun segala sesuatu dilakukan atas namaku.\"",
  ui_story_5052_50520101_67_dialog_content = "\"Karena tanpa nama, kita semua sama.\"",
  ui_story_5052_50520101_68_dialog_content = "Jadi apa tujuan Anda di sini?",
  ui_story_5052_50520101_69_dialog_content = "\"Pada saat ini, tujuan saya adalah untuk berbagi yang unik <color=#FFB400>uji coba</color> denganmu.\"",
  ui_story_5052_50520101_70_option_content = "(Coba gunakan kemampuan psikis)",
  ui_story_5052_50520101_71_dialog_content = "\"Jangan coba menyelami kedalaman kesadaranku, Caelestite. Aku jauh lebih dari yang terlihat.\"",
  ui_story_5052_50520101_72_dialog_content = "(Sial, itu menyadarinya!)",
  ui_story_5052_50520101_73_dialog_content = "\"Tidak semua buku dimaksudkan untuk mata fana. Apakah kamu mengerti?\"",
  ui_story_5052_50520101_74_dialog_content = "(Lalu mengapa kamu mengambil bentuk buku...?)",
  ui_story_5052_50520101_75_dialog_content = "\"Fokus pada yang akan datang <color=#FFB400>uji coba</color>, Caelestite. Aku sudah menyiapkannya khusus untukmu.\"",
  ui_story_5052_50520101_76_dialog_content = "Ya, saya pikir sebanyak itu.",
  ui_story_5052_50520101_77_dialog_content = "May Saya bertanya apa yang diperlukan oleh percobaan ini? Saya belum benar-benar mempersiapkan apa pun, jujur saja.",
  ui_story_5052_50520101_78_dialog_content = "\"Tidak perlu persiapan khusus. Untuk saat ini, jemput aku dan berjalan melewati pintu di ujung lain ruangan.\"",
  ui_story_5052_50520101_79_dialog_content = "\"Tantangan Anda menunggu Anda di sana.\"",
  ui_story_5052_50520101_80_dialog_content = "Baiklah kalau begitu. Uh... M-May Aku menjemputmu sekarang?",
  ui_story_5052_50520101_81_dialog_content = "(Urgh, benda ini lebih berat dari kelihatannya.)",
  ui_story_5052_50520101_82_dialog_content = "(Tidak Victoria bosan membawanya sepanjang waktu?)",
  ui_story_5052_50520101_83_dialog_content = "\"Buka pintunya. Aku akan segera menjelaskan langkah selanjutnya dari persidanganmu.\"",
  ui_story_5052_50520102_1_dialog_content = "\"Bagus sekali, PlayerName.\"",
  ui_story_5052_50520102_2_dialog_content = "\"Kemampuan beradaptasimu telah melampaui ekspektasiku. Bagaimana perasaanmu saat ini?\"",
  ui_story_5052_50520102_3_dialog_content = "Itu jauh berbeda dari pertempuran saya sebelumnya.",
  ui_story_5052_50520102_4_option_content = "Saya merasa hebat!",
  ui_story_5052_50520102_5_dialog_content = "Saya tidak perlu berpikir terlalu banyak. Yang harus saya lakukan adalah memaksa jalan saya melewatinya.",
  ui_story_5052_50520102_6_dialog_content = "Pembatasan gerakan juga jauh lebih santai! Desain yang luar biasa!",
  ui_story_5052_50520102_7_dialog_content = "Jadi mengapa Anda mempersiapkan tantangan ini untuk saya?",
  ui_story_5052_50520102_8_option_content = "Aku tidak yakin...",
  ui_story_5052_50520102_9_dialog_content = "Itu selalu terasa sangat tidak nyata ketika saya bisa bertarung tanpa sebagian besar batasan pertempuran yang biasa.",
  ui_story_5052_50520102_10_dialog_content = "Selain itu, distribusi Lumina jelas telah dirusak, yang membuat pertarungan menjadi semakin tidak realistis.",
  ui_story_5052_50520102_11_dialog_content = "Jadi mengapa Anda mempersiapkan percobaan ini untuk saya?",
  ui_story_5052_50520102_12_option_content = "Bosan keluar dari pikiranku.",
  ui_story_5052_50520102_13_dialog_content = "Rasanya terlalu dibuat-buat, seolah-olah itu dirancang untuk memberi saya pengalaman tempur yang persis seperti ini.",
  ui_story_5052_50520102_14_dialog_content = "Itu tidak banyak tantangan. Nyatanya, kurangnya batasan membuat saya merasa dijamin menang.",
  ui_story_5052_50520102_15_dialog_content = "Sejujurnya, saya lebih suka pertempuran yang lebih realistis dan menantang daripada kemenangan yang mudah.",
  ui_story_5052_50520102_16_dialog_content = "Jadi apa gunanya melalui semua kesulitan merancang uji coba ini?",
  ui_story_5052_50520102_17_dialog_content = "\"Persepsimu setajam sebelumnya, Caelestite.\"",
  ui_story_5052_50520102_18_dialog_content = "Er, w-baiklah aku telah melalui banyak pertempuran, kau tahu? Itu wajar bagi saya untuk memiliki beberapa wawasan tentang mereka.",
  ui_story_5052_50520102_19_dialog_content = "\"Kalau begitu aku berharap untuk melihat kinerjamu di uji coba berikutnya lebih banyak lagi.\"",
  ui_story_5052_50520102_20_dialog_content = "Hah? Masih ada lagi?",
  ui_story_5052_50520102_21_dialog_content = "\"Tentu saja. Apakah kamu mulai merasa lelah?\"",
  ui_story_5052_50520102_22_option_content = "Tidak, saya bersiap untuk pergi!",
  ui_story_5052_50520102_23_dialog_content = "\"Bagus. Kalau begitu mari kita lanjutkan.\"",
  ui_story_5052_50520102_24_dialog_content = "\"Aku ingin sekali melihat seberapa baik kinerjamu, Caelestite...\"",
  ui_story_5052_50520102_25_option_content = "Mungkin aku sedikit lelah...",
  ui_story_5052_50520102_26_dialog_content = "Saya pikir saya perlu beberapa menit untuk istirahat. Lagipula ini semua sangat tiba-tiba.",
  ui_story_5052_50520102_27_dialog_content = "Dimana pintu keluarnya?",
  ui_story_5052_50520102_28_dialog_content = "\"Keluar? Apakah Anda benar-benar percaya Anda bisa pergi sebelum menyelesaikan setiap langkah percobaan Anda?",
  ui_story_5052_50520102_29_dialog_content = "Hah?",
  ui_story_5052_50520102_30_dialog_content = "\"Kesempatan untuk melihat seorang Caelestite dalam pertempuran sangatlah langka. Aku tidak berniat membiarkanmu pergi dengan mudah.\"",
  ui_story_5052_50520102_31_dialog_content = "\"Sekarang mari kita lanjutkan.\"",
  ui_story_5052_50520102_32_dialog_content = "(Untuk menjadi sebuah buku, itu pasti memiliki sikap yang busuk...)",
  ui_story_5052_50520502_1_dialog_content = "\"Selamat, Caelestite. Di atas adalah hasil percobaanmu.\"",
  ui_story_5052_50520502_2_dialog_content = "\"Apakah Anda memiliki pemikiran yang ingin Anda bagikan?\"",
  ui_story_5052_50520502_3_dialog_content = "Nah, ada beberapa hal yang telah mengganggu saya untuk sementara waktu sekarang.",
  ui_story_5052_50520502_4_dialog_content = "Pertama, siapa sebenarnya yang merencanakan semua ini? Apakah itu Anda, atau apakah itu Victoria?",
  ui_story_5052_50520502_5_dialog_content = "Dan dimana anggota lain dari True Order? Sejak saya tiba di sini, saya belum pernah melihat satu pun dari mereka!",
  ui_story_5052_50520502_6_dialog_content = "\"Sebelum aku menjawabmu, aku harus mengajukan pertanyaan lain—\"",
  ui_story_5052_50520502_7_dialog_content = "\"Apakah kamu tahu alasan keberadaan True Order?\"",
  ui_story_5052_50520502_8_option_content = "Untuk mencari Kebenaran.",
  ui_story_5052_50520502_9_dialog_content = "Untuk mencari Kebenaran dan apapun yang berhubungan dengannya, sesuatu seperti itu.",
  ui_story_5052_50520502_10_dialog_content = "Saya tidak begitu yakin, sekarang saya memikirkannya. Apakah ini ada hubungannya dengan percobaan saya?",
  ui_story_5052_50520502_11_dialog_content = "\"Ya, benar.\"",
  ui_story_5052_50520502_12_option_content = "Untuk berkeliling dunia.",
  ui_story_5052_50520502_13_dialog_content = "Anggota True Order memiliki kecenderungan untuk muncul di seluruh dunia, terutama di tempat-tempat yang paling tidak saya harapkan untuk melihat mereka.",
  ui_story_5052_50520502_14_dialog_content = "Pelabuhan, desa, pantai, dan lembah...",
  ui_story_5052_50520502_15_dialog_content = "\"Sebagai pelayan dan pencari Kebenaran, adalah tugas suci mereka untuk mencarinya bahkan di lokasi yang paling terpencil sekalipun.\"",
  ui_story_5052_50520502_16_option_content = "Untuk berbicara banyak omong kosong.",
  ui_story_5052_50520502_17_dialog_content = "Bahkan setelah mengenal begitu banyak orang di True Order begitu lama, saya masih tidak tahu apa yang kalian cari.",
  ui_story_5052_50520502_18_dialog_content = "Sering kali, khotbah Anda yang bertele-tele membuat saya lebih bingung daripada sebelum mendengarkannya.",
  ui_story_5052_50520502_19_dialog_content = "Dan itu berlaku ganda untuk Faust! Pria itu bisa berbicara berjam-jam tanpa mengatakan apa pun yang penting!",
  ui_story_5052_50520502_20_dialog_content = "\"Aku setuju. Bahkan terkadang aku merasa sulit untuk menanggungnya.\"",
  ui_story_5052_50520502_21_dialog_content = "\"Izinkan saya untuk memberikan penjelasan yang lebih sederhana—\"",
  ui_story_5052_50520502_22_dialog_content = "\"Tujuan kami adalah untuk menyelidiki asal-usul dunia ini.\"",
  ui_story_5052_50520502_23_dialog_content = "Asal usul dunia ini?",
  ui_story_5052_50520502_24_dialog_content = "\"Benar. Kami berusaha memahami dari mana asalmu, dan di mana takdirmu berada.\"",
  ui_story_5052_50520502_25_dialog_content = "\"Untuk menemukan makhluk yang memberimu kekuatanmu, dan memastikan apakah makhluk itu terus mengawasi kita semua atau tidak.\"",
  ui_story_5052_50520502_26_dialog_content = "\"Apakah kamu tidak ingin tahu juga?",
  ui_story_5052_50520502_27_dialog_content = "Tunggu, kenapa kau berbicara tentang aku, tiba-tiba?",
  ui_story_5052_50520502_28_dialog_content = "\"...\"",
  ui_story_5052_50520502_29_dialog_content = "\"Itu tidak penting sekarang, Caelestite.\"",
  ui_story_5052_50520502_30_dialog_content = "\"Bagaimanapun, uji coba ini hanyalah upaya pertama kami untuk mengungkap rahasia itu.\"",
  ui_story_5052_50520502_31_dialog_content = "\"Mungkin tidak jelas bagimu sekarang, tapi Kebenaran punya rencana untuk kita semua.\"",
  ui_story_5052_50520502_32_dialog_content = "Rencana apa? Tidak bisakah Anda sedikit lebih spesifik?",
  ui_story_5052_50520502_33_dialog_content = "\"...\"",
  ui_story_5052_50520502_34_dialog_content = "\"Kita akan bertemu sekali lagi dalam waktu dekat, Caelestite.\"",
  ui_story_5052_50520502_35_dialog_content = "\"Ketika hari itu tiba, saya harap Anda akan siap menerima takdir baru Anda.\"",
  ui_story_5052_50520502_36_dialog_content = "Takdir baruku? Apa artinya itu?!",
  ui_story_5052_50520502_37_dialog_content = "\"...\"",
  ui_story_5052_50520502_38_dialog_content = "\"Pintu keluar ada di sana.\"",
  ui_story_5052_50520502_39_dialog_content = "Jadi saya akhirnya bisa pergi sekarang?",
  ui_story_5052_50520502_40_dialog_content = "\"...\"",
  ui_story_5052_50520502_41_dialog_content = "\"...\"",
  ui_story_5052_50520502_42_dialog_content = "(Buku itu tidak merespons lagi.)",
  ui_story_5052_50520502_43_dialog_content = "(Pada akhirnya, itu sama tidak masuk akalnya dengan anggota True Order lainnya...)"
}
return config
